//! Broker-side access policy: token → (principal, role, allowed services).
//!
//! Loaded from the run's access config generated by the test/demo controller
//! into a private per-run directory. Token material never appears in logs,
//! command lines, or receipts; only principal labels do.

use serde::Deserialize;
use std::collections::HashMap;

pub const ROLE_PROVIDER: &str = "provider";
pub const ROLE_CALLER: &str = "caller";

#[derive(Debug, Clone, Deserialize)]
pub struct PolicyEntry {
    pub token: String,
    pub principal: String,
    pub role: String,
    #[serde(default)]
    pub allow: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct AccessPolicyFile {
    pub entries: Vec<PolicyEntry>,
}

/// An authenticated session bound at Hello time.
#[derive(Debug, Clone)]
pub struct Session {
    pub principal: String,
    pub role: String,
    pub allow: Vec<String>,
}

impl Session {
    pub fn is_provider(&self) -> bool {
        self.role == ROLE_PROVIDER
    }
    pub fn may_register(&self, service_id: &str) -> bool {
        self.is_provider() && self.allow.iter().any(|s| s == service_id)
    }
    pub fn may_call(&self, service_id: &str) -> bool {
        self.role == ROLE_CALLER && self.allow.iter().any(|s| s == service_id)
    }
}

#[derive(Debug, Clone)]
pub struct AccessPolicy {
    by_token: HashMap<String, Session>,
}

impl AccessPolicy {
    pub fn from_file(file: AccessPolicyFile) -> Result<Self, String> {
        let mut by_token: HashMap<String, Session> = HashMap::new();
        for e in file.entries {
            if !(e.role == ROLE_PROVIDER || e.role == ROLE_CALLER) {
                return Err(format!("unknown role `{}`", e.role));
            }
            if !autoos_comm_core::ids::is_token_text(&e.token) {
                return Err("credential must be 256-bit token text".to_string());
            }
            if e.principal.is_empty() || e.principal.len() > autoos_comm_core::Limits::MAX_PRINCIPAL
            {
                return Err(format!("bad principal label `{}`", e.principal));
            }
            let session = Session {
                principal: e.principal,
                role: e.role,
                allow: e.allow,
            };
            if by_token.contains_key(&e.token) {
                return Err("duplicate credential entry".to_string());
            }
            by_token.insert(e.token, session);
        }
        Ok(AccessPolicy { by_token })
    }

    pub fn from_json(json: &str) -> Result<Self, String> {
        let file: AccessPolicyFile =
            serde_json::from_str(json).map_err(|e| format!("bad access policy JSON: {e}"))?;
        Self::from_file(file)
    }

    pub fn authenticate(&self, token: &str) -> Option<Session> {
        self.by_token.get(token).cloned()
    }
}
